parameters.jsCode:
// DEV_RIO_402 Scaling Execution — 自動スケーリング判定に基づいてアクション実行。
// DEV_RIO_301 から decision（SCALE/ITERATE/HOLD/STOP）を受け取る。
const i = $input.first().json;
return [{ json: {
  experiment_id: i.experiment_id ?? 'exp-001',
  decision: i.decision ?? 'HOLD',
  rationale: i.rationale ?? '未指定',
  kpi: i.kpi_profit_per_hour ?? 0,
  purchases: i.purchases ?? 0,
  owner_approval: i.owner_yes_no ?? 'PENDING'
} }];

// ルーティング: 判定に基づいて実行アクションを分岐。
const o = $input.first().json;
let action, action_detail, requires_approval;

switch(o.decision) {
  case 'SCALE':
    action = 'INCREASE_PRODUCTION';
    action_detail = `購入発生確認。週産をX2に増やす。メディア拡大候補: Threads/Instagram/Substack`;
    requires_approval = true;
    break;
  case 'ITERATE':
    action = 'TEST_VARIANT';
    action_detail = `遷移ありだが未購入。単一レバー試験: CTA文言/価格/オファー内容から1つ変更`;
    requires_approval = true;
    break;
  case 'HOLD':
    action = 'CONTINUE_OBSERVATION';
    action_detail = 'データ継続取得。1週間後に再判定。';
    requires_approval = false;
    break;
  case 'STOP':
    action = 'ARCHIVE_PROPOSAL';
    action_detail = `十分データで負確認。本コンテンツをアーカイブ候補に移行。（削除はしない・人間確認）`;
    requires_approval = true;
    break;
  default:
    action = 'UNKNOWN';
    action_detail = '判定不明。人間確認待ち。';
    requires_approval = true;
}

return [{ json: { ...o, action, action_detail, requires_approval,
  state: requires_approval ? 'WAITING_APPROVAL' : 'READY_EXECUTE',
  note: `${action} で自動化準備完了。${requires_approval ? 'オーナー Yes で実行。' : '自動実行予定。'}` } }];

// 実行ログ & Slack 通知準備
const o = $input.first().json;
const execId = $execution?.id ?? 'exec-unknown';
const timestamp = new Date().toISOString();

const slack_message = `🤖 Scaling Decision: ${o.action}\n` +
  `Experiment: ${o.experiment_id}\n` +
  `Rationale: ${o.rationale}\n` +
  `Action: ${o.action_detail}\n` +
  (o.requires_approval ? `⚠️ Requires Owner Approval\n` : `✅ Ready for Execution\n`) +
  `Timestamp: ${timestamp}`;

return [{ json: { ...o, execId, timestamp, slack_message, state: 'READY_NOTIFY' } }];

